def solve(nums):
    if not nums:
        return 0
    # patience sorting method
    tails = []
    for x in nums:
        # binary search to find insertion point
        lo, hi = 0, len(tails)
        while lo < hi:
            mid = (lo + hi) // 2
            if tails[mid] < x:
                lo = mid + 1
            else:
                hi = mid
        if lo == len(tails):
            tails.append(x)
        else:
            tails[lo] = x
    return len(tails)

def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    tokens: list of strings representing integers or operators '+', '-', '*', '/'.
    Division truncates toward zero.
    """
    stack = []
    for token in tokens:
        if token in {'+', '-', '*', '/'}:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                res = a + b
            elif token == '-':
                res = a - b
            elif token == '*':
                res = a * b
            else:  # division
                # truncate toward zero
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(token))
    return stack[0] if stack else 0

