def solve(s):
    # Handle non-string or empty input
    if not isinstance(s, str) or not s:
        return 0
    # Remove whitespace and convert to uppercase
    s = s.strip().upper()
    roman = {'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000}
    total = 0
    prev = 0
    for ch in reversed(s):
        val = roman.get(ch, 0)
        if val < prev:
            total -= val
        else:
            total += val
        prev = val
    return total

